; Falls counter, digit printing, in-game keys (F1/S/SPACE/V) and the pause message
; $1aed-$1bc1

; Prints falls_left (falls/lives left of the current player, 0-99) as two decimal digits on the
; status line ("FALLS 04"), at game_screen offset $4A (row 1, column 34).
; Converts by repeated subtraction of 10: bcd_conv_digits counts the tens, bcd_conv_binary keeps the units;
; the packed BCD byte goes to print_hex_byte, which prints it as two digits (both nibbles are 0-9).
; Called at game start and whenever falls_left changes (fall lost, extra fall). Changes A, Y.
show_falls_count
        lda #$00
        sta bcd_conv_digits             ; tens digit = 0
        lda falls_left
        sta bcd_conv_binary
; Binary to decimal: subtract 10 until the value goes negative, counting the tens.
show_falls_tens_loop
        sec
        sbc #$0a
        bcc show_falls_pack_digits
; not executed $1afc-$1b01
        inc bcd_conv_digits
        jmp show_falls_tens_loop
; Undo the last subtraction, then pack tens (high nibble) and units (low nibble) into A.
show_falls_pack_digits
        clc
        adc #$0a
        sta bcd_conv_binary
        lda bcd_conv_digits
        asl
        asl
        asl
        asl
        ora bcd_conv_binary
        ldy #$4a                        ; screen offset: row 1, column 34
        jmp print_hex_byte
; Prints the packed BCD byte in A as two digit characters at game_screen+Y (tens) and game_screen+1+Y
; (units). The digit characters of the game font are $10-$19, so each nibble is ORed with $10.
; Used by the score display (1UP score and TOP score, three BCD bytes each). Changes A.
print_bcd_byte
        pha
        jsr get_high_nibble             ; high nibble to the low bits
        ora #$10                        ; digit character
        sta game_screen,y
        pla
        and #$0f
        ora #$10
        sta $8c01,y
        rts
; In-game key handler. The main loop calls it once per pass in a real game (game_mode = 1), not in the
; attract demo. Sets key_scan_mode (only F1, S, SPACE and V are decoded), runs scan_keyboard, and acts
; on a new key (key_ready = 1), which it acknowledges:
;   F1 ($04)    restart_to_title (does not return)
;   S ($0D)     toggle title_music_off (the title tune on/off) and clear title_music_skip_count
;   SPACE ($3C) toggle_pause (does not return here)
;   V ($1F)     toggle_credit_line (credit text in screen row 0)
; The key code without the shift bit is also stored in last_game_key (nothing reads it).
handle_game_keys
        lda #$01
        sta key_scan_mode               ; nonzero: scan_keyboard decodes only F1, S, SPACE and V
        jsr scan_keyboard
        lda key_ready                   ; key flag: 1 = a new key was seen
        bne handle_game_keys_new_key
        rts
handle_game_keys_new_key
        lda #$00
        sta key_ready                   ; acknowledge the key
        lda key_code
        and #$7f                        ; remove the shift bit
        sta last_game_key
        cmp #$04                        ; F1
        bne handle_game_keys_check_s
        jmp restart_to_title            ; restart the game
handle_game_keys_check_s
        cmp #$0d                        ; S
        bne handle_game_keys_check_space
        lda title_music_off
        eor #$01                        ; toggle the option bit
        sta title_music_off
        lda #$00
        sta title_music_skip_count
        rts
handle_game_keys_check_space
        cmp #$3c                        ; SPACE
        beq handle_game_keys_pause
        cmp #$1f                        ; V
        beq toggle_credit_line
; not executed $1b64-$1b64
        rts
handle_game_keys_pause
        jmp toggle_pause                ; toggle pause (does not return here)
; V key: when the first character of screen row 0 is the blank $20, copies the 40-character credit
; line "BRUCE LEE (C) 1984 DATASOFT REV.2 BY RJF" from version_banner into row 0 of game_screen;
; otherwise fills row 0 with $20. Changes A, X.
toggle_credit_line
        lda #$20
        cmp game_screen                 ; first character of screen row 0
        bne toggle_credit_line_clear
        ldx #$27
toggle_credit_line_copy
        lda version_banner,x
        sta game_screen,x
        dex
        bpl toggle_credit_line_copy
        rts
toggle_credit_line_clear
        ldx #$27
toggle_credit_line_clear_loop
        sta game_screen,x               ; A = $20 (blank)
        dex
        bpl toggle_credit_line_clear_loop
        rts
; Prints A as two hexadecimal digit characters at game_screen+Y and game_screen+1+Y.
; Nibbles 0-9 become characters $10-$19; nibbles A-F become $21-$26 (the letters A-F of the font).
; show_falls_count passes a packed decimal value, so the letter case never occurs there; the unused
; debug_show_values passes real hexadecimal values. Changes A.
print_hex_byte
        pha
        jsr get_high_nibble
        ora #$10
        cmp #$1a                        ; past '9'?
        bcc print_hex_store_high
; not executed $1b8e-$1b90
        clc
        adc #$07                        ; skip to the letters: $1A+7 = $21 'A'
print_hex_store_high
        sta game_screen,y
        pla
        and #$0f
        ora #$10
        cmp #$1a
        bcc print_hex_store_low
; not executed $1b9d-$1b9f
        clc
        adc #$07
print_hex_store_low
        sta $8c01,y
        rts
; Prints message $0B "** PAUSED **" in text line 1 (the status line, screen row 1) at column 15 with
; print_message. The nonzero message number in text_single_height makes the text one row high
; (set_text_row_pointers sends the lower half to io1_dummy). Called by show_paused in toggle_pause.
show_paused_message
        lda #$0b                        ; message number
        sta text_single_height          ; nonzero: single-height text
        ldx #$01
        ldy #$0f
; Shared tail: prints message A at text line X, column Y with print_message, then clears
; text_single_height (back to double-height text).
print_status_row_message
        jsr print_message
        lda #$00
        sta text_single_height
        rts
; Prints message $0C (12 blanks) in text line 1 at column 15, single height, to remove the pause message.
clear_paused_message
        lda #$0c                        ; message number
        sta text_single_height          ; nonzero: single-height text
        ldx #$01
        ldy #$0f
        jmp print_status_row_message
